26	void TraceSender::send(TraceType trace_type, const StackTrace & stack_trace, Int64 size)
27	{
28	    constexpr size_t buf_size = sizeof(char) /// TraceCollector stop flag
29	        + sizeof(UInt8)                      /// String size
30	        + QUERY_ID_MAX_LEN                   /// Maximum query_id length
31	        + sizeof(UInt8)                      /// Number of stack frames
32	        + sizeof(StackTrace::FramePointers)  /// Collected stack trace, maximum capacity
33	        + sizeof(TraceType)                  /// trace type
34	        + sizeof(UInt64)                     /// thread_id
35	        + sizeof(Int64);                     /// size
36	
37	    /// Write should be atomic to avoid overlaps
38	    /// (since recursive collect() is possible)
39	    static_assert(PIPE_BUF >= 512);
40	    static_assert(buf_size <= 512, "Only write of PIPE_BUF to pipe is atomic and the minimal known PIPE_BUF across supported platforms is 512");
41	
42	    char buffer[buf_size];
43	    WriteBufferFromFileDescriptorDiscardOnFailure out(pipe.fds_rw[1], buf_size, buffer);
44	
45	    StringRef query_id;
46	    UInt64 thread_id;
47	
48	    if (CurrentThread::isInitialized())
49	    {
50	        query_id = StringRef(CurrentThread::getQueryId());
51	        query_id.size = std::min(query_id.size, QUERY_ID_MAX_LEN);
52	
53	        thread_id = CurrentThread::get().thread_id;
54	    }
55	    else
56	    {
57	        thread_id = MainThreadStatus::get()->thread_id;
58	    }
59	
60	    writeChar(false, out);  /// true if requested to stop the collecting thread.
61	
62	    writeBinary(static_cast<uint8_t>(query_id.size), out);
63	    out.write(query_id.data, query_id.size);
64	
65	    size_t stack_trace_size = stack_trace.getSize();
66	    size_t stack_trace_offset = stack_trace.getOffset();
67	    writeIntBinary(static_cast<UInt8>(stack_trace_size - stack_trace_offset), out);
68	    for (size_t i = stack_trace_offset; i < stack_trace_size; ++i)
69	        writePODBinary(stack_trace.getFramePointers()[i], out);
70	
71	    writePODBinary(trace_type, out);
72	    writePODBinary(thread_id, out);
73	    writePODBinary(size, out);
74	
75	    out.next();
76	}
