21	ASTPtr ASTProjectionSelectQuery::clone() const
22	{
23	    auto res = std::make_shared<ASTProjectionSelectQuery>(*this);
24	    res->children.clear();
25	    res->positions.clear();
26	
27	#define CLONE(expr) res->setExpression(expr, getExpression(expr, true))
28	
29	    /** NOTE Members must clone exactly in the same order,
30	        *  in which they were inserted into `children` in ParserSelectQuery.
31	        * This is important because of the children's names the identifier (getTreeHash) is compiled,
32	        *  which can be used for column identifiers in the case of subqueries in the IN statement.
33	        * For distributed query processing, in case one of the servers is localhost and the other one is not,
34	        *  localhost query is executed within the process and is cloned,
35	        *  and the request is sent to the remote server in text form via TCP.
36	        * And if the cloning order does not match the parsing order,
37	        *  then different servers will get different identifiers.
38	        */
39	    CLONE(Expression::WITH);
40	    CLONE(Expression::SELECT);
41	    CLONE(Expression::GROUP_BY);
42	    CLONE(Expression::ORDER_BY);
43	
44	#undef CLONE
45	
46	    return res;
47	}
