50	void ASTProjectionSelectQuery::formatImpl(const FormatSettings & s, FormatState & state, FormatStateStacked frame) const
51	{
52	    frame.current_select = this;
53	    frame.need_parens = false;
54	    std::string indent_str = s.one_line ? "" : std::string(4 * frame.indent, ' ');
55	
56	    if (with())
57	    {
58	        s.ostr << (s.hilite ? hilite_keyword : "") << indent_str << "WITH " << (s.hilite ? hilite_none : "");
59	        s.one_line ? with()->formatImpl(s, state, frame) : with()->as<ASTExpressionList &>().formatImplMultiline(s, state, frame);
60	        s.ostr << s.nl_or_ws;
61	    }
62	
63	    s.ostr << (s.hilite ? hilite_keyword : "") << indent_str << "SELECT " << (s.hilite ? hilite_none : "");
64	
65	    s.one_line ? select()->formatImpl(s, state, frame) : select()->as<ASTExpressionList &>().formatImplMultiline(s, state, frame);
66	
67	    if (groupBy())
68	    {
69	        s.ostr << (s.hilite ? hilite_keyword : "") << s.nl_or_ws << indent_str << "GROUP BY " << (s.hilite ? hilite_none : "");
70	        s.one_line ? groupBy()->formatImpl(s, state, frame) : groupBy()->as<ASTExpressionList &>().formatImplMultiline(s, state, frame);
71	    }
72	
73	    if (orderBy())
74	    {
75	        /// Let's convert the ASTFunction into ASTExpressionList, which generates consistent format
76	        /// between GROUP BY and ORDER BY projection definition.
77	        s.ostr << (s.hilite ? hilite_keyword : "") << s.nl_or_ws << indent_str << "ORDER BY " << (s.hilite ? hilite_none : "");
78	        ASTPtr order_by;
79	        if (auto * func = orderBy()->as<ASTFunction>())
80	            order_by = func->arguments;
81	        else
82	        {
83	            order_by = std::make_shared<ASTExpressionList>();
84	            order_by->children.push_back(orderBy());
85	        }
86	        s.one_line ? order_by->formatImpl(s, state, frame) : order_by->as<ASTExpressionList &>().formatImplMultiline(s, state, frame);
87	    }
