90	void ASTProjectionSelectQuery::setExpression(Expression expr, ASTPtr && ast)
91	{
92	    if (ast)
93	    {
94	        auto it = positions.find(expr);
95	        if (it == positions.end())
96	        {
97	            positions[expr] = children.size();
98	            children.emplace_back(ast);
99	        }
100	        else
101	            children[it->second] = ast;
102	    }
103	    else if (positions.contains(expr))
104	    {
105	        size_t pos = positions[expr];
106	        children.erase(children.begin() + pos);
107	        positions.erase(expr);
108	        for (auto & pr : positions)
109	            if (pr.second > pos)
110	                --pr.second;
111	    }
112	}
